      }

      {/* Tweaks panel */}
      <TweaksPanel title="Tweaks">
        <TweakSection title="Direction">
          <TweakRadio
            value={direction}
            onChange={v => setDirection(v)}
            options={[{value: 'A', label: 'A · Workspace'}, {value: 'B', label: 'B · Split'}]}
